#!/usr/bin/env python3
"""d2.py -- S104 D2 probe: locate valence-basis I-matrix asymmetry, row 58, shells 6s/5s.
Criteria pack104/D2-S104-CRITERIA.md hash-gated."""
import sys, os, json, time, hashlib, numpy as np
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, '..', 'rt')); os.chdir(os.path.join(HERE, '..', 'rt'))
p = os.path.join(HERE, 'D2-S104-CRITERIA.md')
if hashlib.sha256(open(p, 'rb').read()).hexdigest() != open(p + '.sha256').read().split()[0]:
    print("HALT rc=3 sha"); sys.exit(3)
import nlchain as NC, hfc2 as H
sys.path.insert(0, '../pack93'); from ffun93 import solve, clone, Ione, Efun, pot
assert H.CORR is False
Zs = 58; ent = (5, 2)
rows = NC.load(); cfg2 = NC.cfg_from_chain(56, rows)
def setq(cfg, a, q):
    d = {(n, l): qq for n, l, qq in cfg}; d[a] = d.get(a, 0) + q
    return [(n, l, qq) for (n, l), qq in sorted(d.items()) if qq > 1e-9]
t0 = time.time(); sol = {}
for q in (0.4, 0.5, 0.6):
    sol[q] = solve(Zs, setq(cfg2, ent, q))[0]
    print("  solved q=%.1f (%ds)" % (q, time.time() - t0), flush=True)
h5, hp, hm = sol[0.5], sol[0.6], sol[0.4]
keys = [(n, l) for n, l, q in h5.occ]; r = h5.r; dr = h5.dr
VAL = {(5, 0), (5, 1), (5, 2), (6, 0)}

def Taction(hh, k):
    Vloc, X = pot(hh, k)
    return hh.eps[k] * hh.P[k] - Vloc * hh.P[k] + X

def resid(hh, k):
    """eigen-relation self-consistency proxy: || (T+Vloc-eps)P - X || with everything from hh"""
    Vloc, X = pot(hh, k)
    T = Taction(hh, k)   # defined BY this identity -> zero by construction; instead measure
    return None

out = {}
for k in [(6, 0), (5, 0)]:
    tag = "%d%s" % (k[0], 'spdf'[k[1]])
    Pp, Pm = hp.P[k].copy(), hm.P[k].copy()
    Tp, Tm = Taction(hp, k), Taction(hm, k)
    if float(np.sum(Pp * h5.P[k] * dr)) < 0: Pp, Tp = -Pp, -Tp
    if float(np.sum(Pm * h5.P[k] * dr)) < 0: Pm, Tm = -Pm, -Tm
    B = {'m': (Pm, Tm), 'p': (Pp, Tp)}
    for kk in keys:
        if kk != k and kk[1] == k[1] and kk in VAL:
            B["%d%s" % (kk[0], 'spdf'[kk[1]])] = (h5.P[kk], Taction(h5, kk))
    names = list(B); nb = len(names)
    M = np.zeros((nb, nb))
    for i, u in enumerate(names):
        for j, v in enumerate(names):
            Pu, _ = B[u]; Pv, Tv = B[v]
            M[i, j] = float(np.sum(Pu * (Tv - (Zs / r) * Pv) * dr))
    print("shell %s basis %s" % (tag, names))
    pairs = {}
    for i in range(nb):
        for j in range(i + 1, nb):
            a = M[i, j] - M[j, i]
            pairs["%s|%s" % (names[i], names[j])] = a
            print("  asym  %-8s % .3e   (M[u,v]=% .6e  M[v,u]=% .6e)"
                  % ("%s|%s" % (names[i], names[j]), a, M[i, j], M[j, i]))
    # orthonormality of the pieces (overlap content that multiplies eps-scale in the identity)
    ovl = {}
    for i, u in enumerate(names):
        for j, v in enumerate(names):
            if i < j:
                ovl["%s|%s" % (u, v)] = float(np.sum(B[u][0] * B[v][0] * dr))
    out[tag] = dict(asym=pairs, overlap=ovl,
                    eps={'m': hm.eps[k], 'p': hp.eps[k],
                         **{n: h5.eps[kk] for kk in keys if kk != k and kk[1] == k[1] and kk in VAL
                            for n in ["%d%s" % (kk[0], 'spdf'[kk[1]])]}})
    print("  overlaps:", {kk: "%.2e" % vv for kk, vv in ovl.items()})
    print("  eps:", {kk: "%.6f" % vv for kk, vv in out[tag]['eps'].items()})
json.dump(out, open(os.path.join(HERE, 'd2-s104.json'), 'w'), indent=1, default=float)
print("receipt d2-s104.json (%ds)" % (time.time() - t0))

